{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울광역청년센터 기능에 청년정책 자료 집적·공유 포함 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울광역청년센터의 기능으로 청년정책 자료를 한데 모아 공유하는 일은 조례에 정해져 있다. 제20조제2항제8호는 정책 수립·운영을 위한 연구조사 및 자료·정보 집적과 공유를 기능으로 명시하고 있다. 따라서 청년정책 자료를 모아 공유하는 일은 서울광역청년센터의 기능에 들어간다.",
          "b_ids": "청년:제20조제2항제8호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "자치구 서울청년센터 기능에 동네 청년 활동 공간 제공 포함 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자치구 서울청년센터의 기능으로 동네에서 청년들이 활동할 공간을 제공하는 일은 조례에 정해져 있다. 제20조제3항제6호는 지역별 청년 활동 공간 및 기반 제공을 기능으로 명시하고 있다. 따라서 생활권(동네)에서 청년이 활동할 공간을 제공하는 일은 자치구 서울청년센터의 기능에 들어간다.",
          "b_ids": "청년:제20조제3항제6호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
